INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (8,6,'生菜 - 洗净 - 去除根部 - 去除枯黄枯黑无法食用部分 - 切碎 - 放入小碗备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (8,7,'酱油 + 蚝油 + 盐 + 胡椒粉 - 搅拌均匀 - 放入小碗备用');
