INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (8,9,'配料 - 待主料煮熟后，生菜单独过一次热水，并与其余配料一同开盖加入主料中搅拌均匀');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (8,10,'酱料 - 待主料煮熟后，与其余配料一同开盖加入主料中搅拌均匀');
