INSERT OR REPLACE INTO recipes (id,title,category_slug,difficulty,calories,likes,favorites,last_updated,github_path,cover_image,summary,ingredients_html,calculation,calculation_html,steps_html,notes_html,markdown_html) VALUES (15,'油酥','condiment',2,111,NULL,NULL,'08/25/2026 10:26:50','dishes/condiment/&#x6CB9;&#x9165;.md','/img/no-image.svg','这是一道中式面点配料，常用于烙饼，能让成品层次分明、外酥里软。主要提供碳水化合物和脂肪，为身体补充能量。做法十分简单，新手友好，预计只需 3 分钟就能调好。','<ul>
<li>面粉</li>
<li>油</li>
<li>盐</li>
</ul>','油 = （要烙饼的张数 * 10ml） 盐 = （要烙饼的张数 / 2）g 面粉 = （要烙饼的张数 / 0.13）g','<ul>
<li>油 = （要烙饼的张数 * 10ml）</li>
<li>盐 = （要烙饼的张数 / 2）g</li>
<li>面粉 = （要烙饼的张数 / 0.13）g</li>
</ul>','<ol>
<li>面粉盛小碗里，加入盐</li>
<li>加入 200 度的热油</li>
<li>用筷子将其搅拌成无固状物体的糊状。</li>
</ol>','<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>','<h1>油酥</h1>
<p>这是一道中式面点配料，常用于烙饼，能让成品层次分明、外酥里软。主要提供碳水化合物和脂肪，为身体补充能量。做法十分简单，新手友好，预计只需 3 分钟就能调好。</p>
<p><strong>估算卡路里：111 kcal</strong></p>
<h2>原料和工具</h2>
<ul>
<li>面粉</li>
<li>油</li>
<li>盐</li>
</ul>
<h2>计算</h2>
<ul>
<li>油 = （要烙饼的张数 * 10ml）</li>
<li>盐 = （要烙饼的张数 / 2）g</li>
<li>面粉 = （要烙饼的张数 / 0.13）g</li>
</ul>
<h2>步骤</h2>
<ol>
<li>面粉盛小碗里，加入盐</li>
<li>加入 200 度的热油</li>
<li>用筷子将其搅拌成无固状物体的糊状。</li>
</ol>
<h2>补充说明</h2>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>');
