INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (46,4,'调汁：将生抽 10 ml 、蚝油 6-8 ml 、盐 0.5 g 、 白糖 1 g 放入碗中调匀，并加入 10-15 ml 清水（凉）搅拌均匀。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (46,5,'再开火，热锅，放入食用油 5-8 ml，油热放入蒜泥。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (46,6,'等待有蒜香飘出，倒入调好的汁，煮沸即可，立马关火。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (46,7,'将锅中的汤汁均匀地 浇 在生菜上。');
INSERT OR REPLACE INTO recipe_images (recipe_id,pos,url,local_file) VALUES (46,0,'/img/no-image.svg','no-image.svg');
