INSERT OR REPLACE INTO recipes (id,title,category_slug,difficulty,calories,likes,favorites,last_updated,github_path,cover_image,summary,ingredients_html,calculation,calculation_html,steps_html,notes_html,markdown_html) VALUES (61,'冬瓜茶','drink',2,296,NULL,NULL,'08/25/2026 10:26:50','dishes/drink/&#x51AC;&#x74DC;&#x8336;.md','/img/no-image.svg','冬瓜茶是一款清爽解暑的传统饮品，口感甘甜柔和，带有冬瓜特有的清香，冰镇后风味更佳。冬瓜本身低热量、富含水分，搭配冰糖熬制，能补充能量、生津止渴。制作不复杂，但对新手而言需要一些耐心，全程大约需要 4 到 5 小时。','<ul>
<li>冬瓜</li>
<li>冰糖</li>
<li>保鲜膜</li>
<li>过滤网</li>
<li>大锅</li>
</ul>','每次制作前需要确定计划做几份。一份正好够 4-5 个人饮用。 每份： 冬瓜 1000g 冰糖 300g','<p>每次制作前需要确定计划做几份。一份正好够 4-5 个人饮用。</p>
<p>每份：</p>
<ul>
<li>冬瓜 1000g</li>
<li>冰糖 300g</li>
</ul>','<ol>
<li><strong>准备冬瓜</strong>：将冬瓜去皮，去籽，切成小块（每块不超过 4cm）。</li>
<li><strong>加入冰糖</strong>：冬瓜加入冰糖，搅拌均匀，盖上保鲜膜放冰箱冷藏 2 小时以上。</li>
<li><strong>煮冬瓜</strong>： 此时冬瓜出了很多水, 倒入锅中 大火煮开，然后转中小火慢慢熬制 1~2 个小时，中途多搅拌防止糊锅。</li>
<li><strong>过滤冬瓜茶</strong>：使用过滤网将煮好的冬瓜茶液过滤，取出冬瓜块，只保留茶液。</li>
<li><strong>冷却</strong>：将冬瓜茶液放凉后，倒入干净的容器中，放入冰箱冷藏即可。</li>
<li><strong>享用</strong>: 熬好的冬瓜茶液是浓缩汁，根据个人喜好添加水或其他饮品，冷热皆宜。</li>
</ol>','<ul>
<li><strong>口感调整</strong>：冰糖的用量可以调整，以达到个人喜好的甜度。</li>
<li><strong>保存方法</strong>：冷藏保存，建议 1 周内喝完。</li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>','<h1>冬瓜茶</h1>
<p>冬瓜茶是一款清爽解暑的传统饮品，口感甘甜柔和，带有冬瓜特有的清香，冰镇后风味更佳。冬瓜本身低热量、富含水分，搭配冰糖熬制，能补充能量、生津止渴。制作不复杂，但对新手而言需要一些耐心，全程大约需要 4 到 5 小时。</p>
<p><strong>估算卡路里：296 kcal</strong></p>
<h2>原料和工具</h2>
<ul>
<li>冬瓜</li>
<li>冰糖</li>
<li>保鲜膜</li>
<li>过滤网</li>
<li>大锅</li>
</ul>
<h2>计算</h2>
<p>每次制作前需要确定计划做几份。一份正好够 4-5 个人饮用。</p>
<p>每份：</p>
<ul>
<li>冬瓜 1000g</li>
<li>冰糖 300g</li>
</ul>
<h2>步骤</h2>
<ol>
<li><strong>准备冬瓜</strong>：将冬瓜去皮，去籽，切成小块（每块不超过 4cm）。</li>
<li><strong>加入冰糖</strong>：冬瓜加入冰糖，搅拌均匀，盖上保鲜膜放冰箱冷藏 2 小时以上。</li>
<li><strong>煮冬瓜</strong>： 此时冬瓜出了很多水, 倒入锅中 大火煮开，然后转中小火慢慢熬制 1~2 个小时，中途多搅拌防止糊锅。</li>
<li><strong>过滤冬瓜茶</strong>：使用过滤网将煮好的冬瓜茶液过滤，取出冬瓜块，只保留茶液。</li>
<li><strong>冷却</strong>：将冬瓜茶液放凉后，倒入干净的容器中，放入冰箱冷藏即可。</li>
<li><strong>享用</strong>: 熬好的冬瓜茶液是浓缩汁，根据个人喜好添加水或其他饮品，冷热皆宜。</li>
</ol>
<h2>补充说明</h2>
<ul>
<li><strong>口感调整</strong>：冰糖的用量可以调整，以达到个人喜好的甜度。</li>
<li><strong>保存方法</strong>：冷藏保存，建议 1 周内喝完。</li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (61,0,'冬瓜');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (61,1,'冰糖');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (61,2,'保鲜膜');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (61,3,'过滤网');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (61,4,'大锅');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (61,0,'准备冬瓜 ：将冬瓜去皮，去籽，切成小块（每块不超过 4cm）。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (61,1,'加入冰糖 ：冬瓜加入冰糖，搅拌均匀，盖上保鲜膜放冰箱冷藏 2 小时以上。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (61,2,'煮冬瓜 ： 此时冬瓜出了很多水, 倒入锅中 大火煮开，然后转中小火慢慢熬制 1~2 个小时，中途多搅拌防止糊锅。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (61,3,'过滤冬瓜茶 ：使用过滤网将煮好的冬瓜茶液过滤，取出冬瓜块，只保留茶液。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (61,4,'冷却 ：将冬瓜茶液放凉后，倒入干净的容器中，放入冰箱冷藏即可。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (61,5,'享用 : 熬好的冬瓜茶液是浓缩汁，根据个人喜好添加水或其他饮品，冷热皆宜。');
INSERT OR REPLACE INTO recipe_images (recipe_id,pos,url,local_file) VALUES (61,0,'/img/no-image.svg','no-image.svg');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (61,0,'冬瓜 1000g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (61,1,'冰糖 300g');
INSERT OR REPLACE INTO recipes (id,title,category_slug,difficulty,calories,likes,favorites,last_updated,github_path,cover_image,summary,ingredients_html,calculation,calculation_html,steps_html,notes_html,markdown_html) VALUES (62,'酱炖蟹','aquatic',3,468,NULL,NULL,'08/25/2026 10:26:50','dishes/aquatic/&#x9171;&#x7096;&#x87F9;.md','/img/no-image.svg','这道菜是浙江平湖地区的秋日限定咸鲜风味，蟹黄绵润裹着酱香，蟹肉清甜，汤汁拌饭一绝。富含优质蛋白和微量元素。难度适中，适合有基础的新手，从准备到出锅大约 30 分钟。','<ul>
<li>螃蟹（首选河蟹，次选梭子蟹）</li>
<li>豆瓣酱</li>
<li>冰糖（可选）</li>
<li>老抽</li>
<li>菜油（未脱色的菜籽油，俗称“毛菜油”或“土菜油”，备选花生油）</li>
<li>番茄酱</li>
<li>料酒</li>
<li>老姜</li>
<li>小葱</li>
<li>鸡蛋（可选）</li>
<li>猪肉末（可选）</li>
</ul>','每次制作前需要确定计划做几份。一份正好够 2 个人吃。 每份： 螃蟹 500 g（约 3-4 只中等河蟹） 豆瓣酱 30-50 g 冰糖 0-15 g 老抽 15 ml 菜油 20 ml 番茄酱 15 ml 料酒 5 ml 老姜 10 g 葱 10 g 鸡蛋 1 个（约 50 g） 猪肉末 50 g 水 500 mL','<p>每次制作前需要确定计划做几份。一份正好够 2 个人吃。</p>
<p>每份：</p>
<ul>
<li>螃蟹 500 g（约 3-4 只中等河蟹）</li>
<li>豆瓣酱 30-50 g</li>
<li>冰糖 0-15 g</li>
<li>老抽 15 ml</li>
<li>菜油 20 ml</li>
<li>番茄酱 15 ml</li>
<li>料酒 5 ml</li>
<li>老姜 10 g</li>
<li>葱 10 g</li>
<li>鸡蛋 1 个（约 50 g）</li>
<li>猪肉末 50 g</li>
<li>水 500 mL</li>
</ul>','<ol>
<li>把螃蟹刷洗干净，然后在砧板上对半劈开</li>
<li>锅里下菜油，放入姜末和豆瓣酱爆香，加入冰糖炒化，直到冒小气泡就盛出</li>
<li>在盘子里铺上一层酱，然后把切好的螃蟹切开面朝下，整齐排放在酱上</li>
<li>放点葱段和姜片，建议敲个鸡蛋或在盘底铺肉末</li>
<li>上锅蒸 10-12 分钟</li>
</ol>','<ul>
<li>咸口放 50 g 豆瓣酱，甜口减少豆瓣酱的用量并加入冰糖和番茄酱</li>
<li>出锅后再撒上一点葱花会更香也更好看</li>
<li>参考资料：<a href="https://tidenews.com.cn/news.html?id=2925971">秋风起，平湖这道美味很下饭_潮新闻官网</a></li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>','<h1>酱炖蟹</h1>
<p>这道菜是浙江平湖地区的秋日限定咸鲜风味，蟹黄绵润裹着酱香，蟹肉清甜，汤汁拌饭一绝。富含优质蛋白和微量元素。难度适中，适合有基础的新手，从准备到出锅大约 30 分钟。</p>
<p><strong>估算卡路里：468 kcal</strong></p>
<h2>原料和工具</h2>
<ul>
<li>螃蟹（首选河蟹，次选梭子蟹）</li>
<li>豆瓣酱</li>
<li>冰糖（可选）</li>
<li>老抽</li>
<li>菜油（未脱色的菜籽油，俗称“毛菜油”或“土菜油”，备选花生油）</li>
<li>番茄酱</li>
<li>料酒</li>
<li>老姜</li>
<li>小葱</li>
<li>鸡蛋（可选）</li>
<li>猪肉末（可选）</li>
</ul>
<h2>计算</h2>
<p>每次制作前需要确定计划做几份。一份正好够 2 个人吃。</p>
<p>每份：</p>
<ul>
<li>螃蟹 500 g（约 3-4 只中等河蟹）</li>
<li>豆瓣酱 30-50 g</li>
<li>冰糖 0-15 g</li>
<li>老抽 15 ml</li>
<li>菜油 20 ml</li>
<li>番茄酱 15 ml</li>
<li>料酒 5 ml</li>
<li>老姜 10 g</li>
<li>葱 10 g</li>
<li>鸡蛋 1 个（约 50 g）</li>
<li>猪肉末 50 g</li>
<li>水 500 mL</li>
</ul>
<h2>步骤</h2>
<ol>
<li>把螃蟹刷洗干净，然后在砧板上对半劈开</li>
<li>锅里下菜油，放入姜末和豆瓣酱爆香，加入冰糖炒化，直到冒小气泡就盛出</li>
<li>在盘子里铺上一层酱，然后把切好的螃蟹切开面朝下，整齐排放在酱上</li>
<li>放点葱段和姜片，建议敲个鸡蛋或在盘底铺肉末</li>
<li>上锅蒸 10-12 分钟</li>
</ol>
<h2>补充说明</h2>
<ul>
<li>咸口放 50 g 豆瓣酱，甜口减少豆瓣酱的用量并加入冰糖和番茄酱</li>
<li>出锅后再撒上一点葱花会更香也更好看</li>
<li>参考资料：<a href="https://tidenews.com.cn/news.html?id=2925971">秋风起，平湖这道美味很下饭_潮新闻官网</a></li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>');
