INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (94,0,'鸡蛋两个，亦可选择两个蛋清，一个蛋黄。');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (94,1,'纯干燕麦片 50g （大约等同一个鸡蛋的量）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (94,2,'牛奶一盒 约 250ml');
