INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (97,16,'豆芽放置凉皮上、面筋随后放上。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (97,17,'将调配好的芝麻酱从面筋上方倒下。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (97,18,'撒上黄瓜丝。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (97,19,'如有喜爱可以加入辣椒油。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (97,20,'色香味俱全的家常凉皮出炉！');
