INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,0,'在碗中混合烤鹰嘴豆粉 120g、切碎的洋葱、青辣椒、生姜');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,1,'加入孜然籽 3g、芝麻 5g、红辣椒粉 3g、印度黑盐 3g、盐 3g');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,2,'加入芥末油 15ml、柠檬汁 10ml、切碎的香菜叶');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,3,'充分混合均匀，馅料应呈松散但可捏合的状态，备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,4,'将全麦面粉 200g 放入大碗中');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,5,'逐渐加入温水，边加边揉，揉成 光滑柔软 的面团');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,6,'面团静置 15 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,7,'将面团分成 8 个等大的小剂子');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,8,'每个剂子用手压成一个直径约 8cm 的圆形面片（中间稍厚）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,9,'在面片中央放入约 15g 馅料');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,10,'将面片四周收拢包住馅料，封口处捏紧，搓成圆球');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,11,'烤箱预热至 200°C');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,12,'将利提放在烤盘上，烤 25-30 分钟 ，期间翻面一次，直至 表面金棕色且有裂纹');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,13,'如果使用明火：将利提直接放在炭火或煤气灶小火上烤，不断翻转，直至 均匀焦黄');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,14,'烤好后趁热将每个利提表面涂上酥油，使其 浸润吸收');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,15,'将茄子、番茄、土豆放在明火上直接烤，或放入 200°C 烤箱烤 20-25 分钟 ，直至 外皮焦黑、内部完全软烂');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,16,'烤好后去皮，将茄子、番茄、土豆分别用叉子或手捣碎');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,17,'将捣碎的蔬菜混合在一起');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,18,'加入切碎的大蒜、青辣椒、盐 4g、芥末油 15ml');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,19,'充分搅拌混合均匀');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,20,'撒上香菜叶装饰');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,21,'将利提摆盘，旁边放上巧卡蔬菜泥');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (103,22,'趁热食用，用手掰开利提蘸巧卡');
