INSERT OR REPLACE INTO recipes (id,title,category_slug,difficulty,calories,likes,favorites,last_updated,github_path,cover_image,summary,ingredients_html,calculation,calculation_html,steps_html,notes_html,markdown_html) VALUES (143,'猪肉烩酸菜','meat_dish',5,1817,NULL,NULL,'08/25/2026 10:26:50','dishes/meat_dish/&#x732A;&#x8089;&#x70E9;&#x9178;&#x83DC;.md','/img/no-image.svg','猪肉烩酸菜是一道北方家常炖菜，酸香浓郁，五花肉软烂，排骨入味。主要提供蛋白质，酸菜也带来乳酸菌等有益成分。做法步骤清晰，新手也能按部就班完成，但需耐心慢炖，从头到尾大约需要 3 小时。','<ul>
<li>猪五花肉或猪肉排骨</li>
<li>东北酸菜</li>
<li>大葱</li>
<li>姜</li>
<li>蒜</li>
<li>盐</li>
<li>生抽酱油</li>
<li>五香粉</li>
<li>料酒</li>
<li>大料</li>
</ul>','按照 3-5 个人吃的量： 猪排骨或者五花肉（总共） 1500 克 东北酸菜 1000 克 大葱 1 根 姜 100 克 蒜 4 瓣 盐 10 克 生抽酱油 15 克 五香粉 10 克 料酒 20 毫升 大料 2 颗','<p>按照 3-5 个人吃的量：</p>
<ul>
<li>猪排骨或者五花肉（总共） 1500 克</li>
<li>东北酸菜 1000 克</li>
<li>大葱 1 根</li>
<li>姜 100 克</li>
<li>蒜 4 瓣</li>
<li>盐 10 克</li>
<li>生抽酱油 15 克</li>
<li>五香粉 10 克</li>
<li>料酒 20 毫升</li>
<li>大料 2 颗</li>
</ul>','<ol>
<li>大葱切段；生姜 50 克切段， 50 克切末；大蒜切末，备用。</li>
<li>全部酸菜切丝，用水冲洗 2 ～ 3 遍备用。
-冲洗次数取决于个人口味，喜欢酸味，可以冲洗 2 遍。害怕酸味，可以冲洗 3 ～ 4 遍。不能不冲洗，否则会过酸。</li>
<li>排骨和五花肉入锅，倒入冷水淹没。放入全部葱段， 50 克生姜段和料酒 20 毫升。大火煮开后，等待 5 分钟。关火，将排骨和五花肉捞出，冷水冲洗掉浮沫，备用</li>
<li>煮好的五花肉切片或者切块，备用。</li>
<li>将之前的锅洗干净，并且擦干（不然加入油会崩出来）。</li>
<li>锅中加入油，开中火，放入姜蒜末爆香，放入五花肉和排骨。将五花肉和排骨煎至金黄，倒入 10 克五香粉和 15 克 生抽酱油，用铲子翻动 1 ～ 2 分钟。</li>
<li>将冲洗好的酸菜丝加入锅中，翻炒 3 分钟。</li>
<li>倒入纯净水至刚好没过食材，加入 2 颗大料，转大火，直到锅中水沸腾。转中火，盖锅盖焖煮。</li>
<li>等待 1.5 ～ 2 小时，直至五花肉软烂 （可以用筷子轻松扎穿）</li>
<li>掀开锅盖，开大火收汤，翻动锅中食材直至锅中剩余水分只覆盖锅底，转小火，准备调味。</li>
<li>调味：加入食用盐 10 克，搅拌均匀。</li>
<li>关火，出锅。</li>
</ol>','<ul>
<li>大火收汤时，注意不要糊锅，可以适当翻动来检查水位。</li>
<li>调味的技巧，最后加盐时，可以一点一点加入，搅拌后品尝味道，直到可以接受的口味</li>
<li>本菜品有酸菜的特殊风味</li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>','<h1>猪肉烩酸菜</h1>
<p>猪肉烩酸菜是一道北方家常炖菜，酸香浓郁，五花肉软烂，排骨入味。主要提供蛋白质，酸菜也带来乳酸菌等有益成分。做法步骤清晰，新手也能按部就班完成，但需耐心慢炖，从头到尾大约需要 3 小时。</p>
<p><strong>估算卡路里：1817 kcal</strong></p>
<h2>原料和工具</h2>
<ul>
<li>猪五花肉或猪肉排骨</li>
<li>东北酸菜</li>
<li>大葱</li>
<li>姜</li>
<li>蒜</li>
<li>盐</li>
<li>生抽酱油</li>
<li>五香粉</li>
<li>料酒</li>
<li>大料</li>
</ul>
<h2>计算</h2>
<p>按照 3-5 个人吃的量：</p>
<ul>
<li>猪排骨或者五花肉（总共） 1500 克</li>
<li>东北酸菜 1000 克</li>
<li>大葱 1 根</li>
<li>姜 100 克</li>
<li>蒜 4 瓣</li>
<li>盐 10 克</li>
<li>生抽酱油 15 克</li>
<li>五香粉 10 克</li>
<li>料酒 20 毫升</li>
<li>大料 2 颗</li>
</ul>
<h2>步骤</h2>
<ol>
<li>大葱切段；生姜 50 克切段， 50 克切末；大蒜切末，备用。</li>
<li>全部酸菜切丝，用水冲洗 2 ～ 3 遍备用。
-冲洗次数取决于个人口味，喜欢酸味，可以冲洗 2 遍。害怕酸味，可以冲洗 3 ～ 4 遍。不能不冲洗，否则会过酸。</li>
<li>排骨和五花肉入锅，倒入冷水淹没。放入全部葱段， 50 克生姜段和料酒 20 毫升。大火煮开后，等待 5 分钟。关火，将排骨和五花肉捞出，冷水冲洗掉浮沫，备用</li>
<li>煮好的五花肉切片或者切块，备用。</li>
<li>将之前的锅洗干净，并且擦干（不然加入油会崩出来）。</li>
<li>锅中加入油，开中火，放入姜蒜末爆香，放入五花肉和排骨。将五花肉和排骨煎至金黄，倒入 10 克五香粉和 15 克 生抽酱油，用铲子翻动 1 ～ 2 分钟。</li>
<li>将冲洗好的酸菜丝加入锅中，翻炒 3 分钟。</li>
<li>倒入纯净水至刚好没过食材，加入 2 颗大料，转大火，直到锅中水沸腾。转中火，盖锅盖焖煮。</li>
<li>等待 1.5 ～ 2 小时，直至五花肉软烂 （可以用筷子轻松扎穿）</li>
<li>掀开锅盖，开大火收汤，翻动锅中食材直至锅中剩余水分只覆盖锅底，转小火，准备调味。</li>
<li>调味：加入食用盐 10 克，搅拌均匀。</li>
<li>关火，出锅。</li>
</ol>
<h2>补充说明</h2>
<ul>
<li>大火收汤时，注意不要糊锅，可以适当翻动来检查水位。</li>
<li>调味的技巧，最后加盐时，可以一点一点加入，搅拌后品尝味道，直到可以接受的口味</li>
<li>本菜品有酸菜的特殊风味</li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,0,'猪五花肉或猪肉排骨');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,1,'东北酸菜');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,2,'大葱');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,3,'姜');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,4,'蒜');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,5,'盐');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,6,'生抽酱油');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,7,'五香粉');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,8,'料酒');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (143,9,'大料');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,0,'大葱切段；生姜 50 克切段， 50 克切末；大蒜切末，备用。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,1,'全部酸菜切丝，用水冲洗 2 ～ 3 遍备用。 -冲洗次数取决于个人口味，喜欢酸味，可以冲洗 2 遍。害怕酸味，可以冲洗 3 ～ 4 遍。不能不冲洗，否则会过酸。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,2,'排骨和五花肉入锅，倒入冷水淹没。放入全部葱段， 50 克生姜段和料酒 20 毫升。大火煮开后，等待 5 分钟。关火，将排骨和五花肉捞出，冷水冲洗掉浮沫，备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,3,'煮好的五花肉切片或者切块，备用。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,4,'将之前的锅洗干净，并且擦干（不然加入油会崩出来）。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,5,'锅中加入油，开中火，放入姜蒜末爆香，放入五花肉和排骨。将五花肉和排骨煎至金黄，倒入 10 克五香粉和 15 克 生抽酱油，用铲子翻动 1 ～ 2 分钟。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,6,'将冲洗好的酸菜丝加入锅中，翻炒 3 分钟。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,7,'倒入纯净水至刚好没过食材，加入 2 颗大料，转大火，直到锅中水沸腾。转中火，盖锅盖焖煮。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,8,'等待 1.5 ～ 2 小时，直至五花肉软烂 （可以用筷子轻松扎穿）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,9,'掀开锅盖，开大火收汤，翻动锅中食材直至锅中剩余水分只覆盖锅底，转小火，准备调味。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,10,'调味：加入食用盐 10 克，搅拌均匀。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (143,11,'关火，出锅。');
