INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,0,'在大碗中混合酸奶、生姜泥、大蒜泥、红辣椒粉、姜黄粉、盐、柠檬汁');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,1,'放入鸡肉块，充分裹上腌料');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,2,'盖保鲜膜，冷藏腌制 至少 1 小时');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,3,'在平底锅中倒入 15ml 食用油，大火加热');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,4,'将腌好的鸡肉块放入锅中（不要倒入腌料汁）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,5,'大火煎至 两面焦黄 （每面约 3 分钟），鸡肉不需要完全煮熟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,6,'盛出备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,7,'在锅中放入番茄块、洋葱块、腰果、生姜、大蒜和水 100ml');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,8,'大火煮沸后转中火， 煮 15 分钟 ，直至 所有材料完全软烂');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,9,'稍微冷却后，倒入搅拌机中打成 细腻顺滑的泥状');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,10,'用滤网过滤一遍，去除渣滓，得到顺滑的酱汁，备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,11,'在炒锅中放入黄油 50g，中火加热融化');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,12,'倒入过滤好的番茄酱汁');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,13,'加入红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 5g');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,14,'翻炒 3-5 分钟 ，直至 酱汁颜色变深且油花浮出');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,15,'放入烤好的鸡肉块，翻拌均匀');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,16,'加入糖 10g（平衡番茄的酸味），搅拌');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,17,'倒入淡奶油 100ml，搅拌均匀');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,18,'小火 炖 10-12 分钟 ，使鸡肉完全熟透且吸收酱汁');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,19,'加入印度综合香料粉 3g、小豆蔻粉 2g');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,20,'撒入干葫芦巴叶 3g（用手搓碎后撒入）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,21,'搅拌均匀，关火');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (153,22,'盛盘，可额外淋上少量淡奶油作为装饰');
