INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (178,2,'香葱 一根');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (178,3,'姜 一块');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (178,4,'胡椒粉 3-5 g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (178,5,'食用油 15 ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (178,6,'食用盐 10-15 g');
