INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,0,'排骨 500-800g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,1,'玉米一根（喜欢吃玉米的可以多一根）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,2,'胡萝卜一根（喜欢吃胡箩卜的可以多一根）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,3,'大葱小半根');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,4,'香葱一根');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,5,'食用油 10 ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,6,'黑胡椒粉 4g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,7,'料酒 10ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,8,'醋 10ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (180,9,'食用盐 10-15g（根据最后汤剩余的量而定）');
