INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,0,'烤箱（电饭锅可替代，但大多情况下由于锅胆材质问题易失败）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,1,'打蛋器（电动最好，手动费力且有一定失败概率）或筷子（非常不推荐）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,2,'铝合金阳极模具（千万不能选不沾模具，常用尺寸为 6 寸或 8 寸）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,3,'刮刀（用于翻拌蛋糕糊）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,4,'鸡蛋');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,5,'白糖');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,6,'牛奶（或水）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,7,'食用油（或黄油，但需加热软化）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,8,'低筋面粉（推荐惠宜）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (191,9,'[可选] 柠檬汁或白醋');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,0,'从冰箱中取出新鲜的鸡蛋');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,1,'准备两个容器并擦干，分别盛放蛋清与蛋黄');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,2,'对盛放蛋清的容器，可稍有水珠，但 不能有任何油 ；盛放蛋黄的容器不能有水珠');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,3,'打蛋，手工或利用分蛋器，将蛋清与蛋黄分离到两个容器中。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,4,'分离过程中蛋黄不能破碎， 蛋清中不能混有任何蛋黄 ，否则会严重影响打发。（白色系带可进入蛋清，不影响）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,5,'（注意，不使用厨房机的情况下，盛放蛋清的容器也是打蛋的容器，为避免溢出，加入全部蛋清后不要超过容器的 1/8 ）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,6,'准备一个新的空碗，加入配方中 全部的食用油 和 全部的牛奶');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,7,'用打蛋器手动快速搅拌，直到油水完全融合，呈现乳白色悬浊液状态（完成乳化）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,8,'将配方中 全部的低筋面粉 过筛，加入上述乳化液中。用刮刀以”Z 字形”划拌至没有明显干粉即可（此时面糊可能会有些粗糙，属于正常现象）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,9,'将分离好的 全部蛋黄 加入碗中，继续用刮刀”Z 字形”划拌');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,10,'此时面糊会变得非常细腻顺滑，且不易产生面筋。将其静置备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,11,'准备好剩余 3/4 的白糖。分为三份，每份为总量的 1/4');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,12,'蛋清中加入柠檬汁或白醋（可选）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,13,'打蛋器中速，打发蛋白至有 粗大气泡的状态 ，加入 第一份白糖');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,14,'打蛋器高速，打发蛋白至 气泡较细腻的状态 ，加入 第二份白糖');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,15,'打蛋器高速，打发蛋白至”湿性发泡”的状态，加入 第三份白糖');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,16,'打蛋器中低速，打发蛋白至”干性发泡”的状态');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,17,'此时蛋白打发程度已符合要求');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,18,'简单搅拌几下蛋黄液');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,19,'用刮刀取 1/3 的蛋白霜，加入到蛋黄糊中');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,20,'采用“翻拌”的手法，此手法是为了避免消泡');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,21,'将 1/3 的蛋白霜与蛋黄液的混合液倒入剩余 2/3 的蛋白霜中，继续翻拌均匀');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,22,'将蛋糕糊倒入模具，震荡几下避免大气泡');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,23,'烘烤总时间：6 寸蛋糕 30-35 分钟，8 寸蛋糕 50 分钟。根据自己烤箱特性灵活调整，一般不超过 \(\pm 5\) 分钟。（最后几分钟时可在烤箱前观察）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,24,'以 上管 150 摄氏度，下管 160 摄氏度 预热烘烤，约 10 分钟可到达预定温度。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,25,'预热完成后，将模具放入烤箱下层');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,26,'选择 变温烘烤 ，分为两个阶段。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,27,'烤好后，出炉');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,28,'预热：空气炸锅设置 130°C 预热 5 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,29,'入锅与遮盖：将装有蛋糕糊的模具放入炸锅。 立刻在模具上方盖上一层锡纸 （亮面朝上，哑光面接触食物），锡纸边缘捏紧，防止被热风吹开');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,30,'第一阶段烘烤：设置 130°C ，烘烤 35 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,31,'第二阶段上色：打开炸锅， 撤掉锡纸 。将温度调高至 150°C ，继续烘烤 10–15 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,32,'判断熟透：蛋糕顶部膨胀且上色呈金黄色即可出锅。用牙签扎入中心，拔出后没有湿润面糊带出即代表已烤熟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,33,'出锅后的震热气与倒扣脱模操作，与烤箱版完全一致');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,34,'（可选） 将模具从高处落下，震出其中的热气');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,35,'模具倒扣 10 分钟，使蛋糕冷却');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (191,36,'脱模，食用');
