INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (213,8,'开 大火 蒸 5 分钟 ，要保持锅中水一直处于沸腾状态，否则要延长时间。每隔 2 分钟 开盖一次释放水蒸气，开盖过晚蛋羹容易变成蜂窝状；开盖太早/频繁蒸的时间需要久一些。');
