INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (232,12,'沥干糯米，放入蒸布中，隔水蒸 40 ～ 60 分钟。每 20 分钟打开锅盖翻动一次确保蒸熟均匀');
