INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (234,3,'黄冰糖 100 克');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (234,4,'山楂片 30 克');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (234,5,'甘草 2 克');
