INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,4,'将 40g 味淋 （或 30g 料酒 ），30g 酱油 ，20g 耗油 ，5g 糖 ，5g 老抽 （可选，用于调色），在碗中搅拌混合成 调料 （该步骤可直接将碗放在电子秤上进行）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,5,'热油锅放入洋葱， 快速翻炒 至洋葱 变透明状');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,6,'关小火，加入 250g 水（或出汁），开回大火加热 等待 3 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,7,'加入牛肉和 调料');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,8,'不断翻动 所有食材 10 分钟 ，防止食材粘锅');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,9,'关火');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,10,'盛装肥牛丼至 米饭 上（注意要把汁水淋一些在饭上）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,11,'撒上葱花和白芝麻，制作完成。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,12,'微波炉：单人份高火 2-3 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (278,13,'锅：需额外加 50ml 水，加热时需 不断翻动');
