INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (286,7,'大蒜和小米辣剁成沫，放上 10g 辣椒粉，5g 花生碎，热油搅拌均匀。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (286,8,'再加入 10ml 酱油，10ml 醋，5g 白糖，3g 鸡精，3g 盐搅拌均匀。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (286,9,'将调味料倒在凉粉上，然后撒上香菜即可。');
