INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (304,10,'1 小时后，开大火收汁直到酱汁浓稠，呈现有光泽的琥珀色，即完成。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (304,11,'炖煮结束后，乘一碗米饭，将软烂的卤肉浇在米饭上，并加上卤蛋，开始享用。');
