INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,1,'处理葱姜： 将 30g 姜全部切成薄片（分成两份 15g）。将 25g 小葱处理好：15g 挽成一个葱结，剩余 10g 切成细小葱花备用。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,2,'封装酱汁碗（一键调用）： 拿一个小碗，依次加入 10ml 生抽、5ml 老抽、5ml 蚝油、5ml 黄豆酱，彻底搅拌均匀，放在灶台触手可及处备用。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,3,'封装香料碟（一键调用）： 拿一个小碟，放入 5g 干辣椒、1g 八角（约 1-2 颗）、1g 花椒（约 10 粒）、1g 桂皮（一小块），以及刚才切好的 15g 姜片，备用。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,4,'开启异步水程： 按下电热水壶开关，开始烧制 700ml 开水。（确保炒制完成时，开水刚好就绪）。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,5,'冷水焯水： 将 750g 肋排冷水下锅，加入 15g 葱结、15g 姜片、15ml 料酒。大火煮沸后，继续保持沸腾焯水 2 分钟，逼出内部血沫。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,6,'热洗冷防： 捞出排骨， 必须用热水 将排骨表面残留的浮沫清洗干净（遇冷水肉质会剧烈收缩变硬）。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,7,'绝对脱水（防爆防溅）： 洗净的排骨 必须用厨房纸彻底吸干表面水分 ，装盘放在炒锅旁边备用（防止后续下入高温糖色时发生剧烈炸锅）。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,8,'炒制糖色： 热锅凉油，加入 20ml 食用油。将 10g 白糖倒入锅中，中小火不停搅拌。翻炒至白糖完全融化冒泡，并呈现红棕色的焦糖色 。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,9,'上色煎制： 迅速加入彻底脱水的 750g 排骨，转中大火翻炒。煎制约 2-3 分钟，至排骨两面微微金黄，且均匀裹满焦糖色。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,10,'一键爆香： 在锅中拨出一小块空地， 直接倒入【香料碟】 。利用锅底的热油爆香约 10 秒，激发出香料的脂溶性香气。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,11,'一键调味： 顺着热锅边缘淋入剩余的 10ml 料酒激发出锅气。紧接着 直接倒入【酱汁碗】 ，翻炒约 30 秒，让酱料完全包裹排骨并炒出浓郁酱香。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,12,'加水长炖： 此时电热水壶已沸腾，直接加入 700ml 滚烫的开水（水量需没过排骨），大火烧开。随后盖上锅盖，转小火持续焖煮 40 分钟。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,13,'加入土豆： 40 分钟后打开锅盖，将泡在水里的 300g 土豆捞出沥干，下入锅中。重新盖上锅盖，继续小火焖煮 15-20 分钟，直到用筷子能轻松扎透土豆块。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,14,'调味收汁： 打开锅盖，加入 3g 盐（此时可尝一下汤汁，根据个人口味酌情微调）。转大火开始翻炒收汁，大约需要 3-5 分钟。直到汤汁变得浓稠，均匀地挂在排骨和土豆上即可关火。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (307,15,'点缀出锅： 盛盘出锅，在表面均匀撒上预处理好的 10g 葱花作为 UI 点缀即可。');
