INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (307,4,'料酒 = 25ml （分为两份：15ml 焯水用，10ml 炒制用）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (307,5,'白糖 = 10g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (307,6,'干辣椒 = 5g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (307,7,'八角 = 1g （约 1-2 颗）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (307,8,'花椒 = 1g （约 10 粒）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (307,9,'桂皮 = 1g （一小块）');
