INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (307,11,'老抽 = 5ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (307,12,'蚝油 = 5ml');
