INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (327,0,'注：如果有可能，请尽量把刀磨的锋利一些。');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (327,1,'主料： 大肉 、 鸡蛋 （可选）、 豆皮 （可选）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (327,2,'辅料： 生姜 、 冰糖 、 生抽 、 老抽 、 料酒 、 香叶 、 八角 、 盐 、 水 、 葱 （记得要开水）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,0,'猪五花肉 切大块（约 4.5cm ，冷冻半小时至一小时更好切）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,1,'豆皮 切 2cm 的宽度');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,2,'生姜 切片（每片厚度约 3mm ）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,3,'水 烧开');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,4,'鹌鹑蛋 煮熟并用 叉子 / 牙签 扎孔（尽量多些好入味）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,5,'大葱 大葱白色的部分 葱白');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,6,'冷水锅中放入切好的 猪五花肉 ，加入料酒与葱姜，煮 15 分钟去掉血腥');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,7,'锅中放入两片 生姜 提味');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,8,'开中小火后直接加入 五花肉 ，不需要放入食用油，每块 五花肉 六个面都煎一下，煎至出油即可');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,9,'将煎出的油倒出备用，并将 五花肉 推至一边，加入 15g 冰糖 ，翻炒至 冰糖 融化；');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,10,'融化后将五花肉与冰糖炒至融合上色，加入');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,11,'加入 烧好的开水 炖煮 40 分钟（刀工差的同学切的过大请自觉延长炖煮时间），并放入');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,12,'盖上锅盖煮至沸腾后，加入煮好扎好孔的 鹌鹑蛋 和 豆皮 ，开中小火，等待 40 分钟。（中途可适当翻搅防止粘锅）；');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,13,'打开锅盖，待汤汁快没有的时候开大火收汁（切记不可收干）；');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (327,14,'加入 2-3g 盐 ，翻炒一下，就可以出锅了。');
