INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,2,'冰糖：15 克（约 7 块）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,3,'生抽：10ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,4,'老抽：15ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,5,'料酒：5ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,6,'开水：没过食材的量，需要 600ml-900ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,7,'香叶：3 片');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,8,'八角：2 个');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,9,'鹌鹑蛋（可选，没有鹌鹑蛋，可以用同等重量的鸡蛋代替）：0-2 个');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (327,10,'豆皮（可选）：0-80g');
