INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (336,3,'野山椒 10 克');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (336,4,'青红辣椒 20 克');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (336,5,'大蒜 30-50 克 （可以根据口味偏好调整，最好不低于 30 克）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (336,6,'豆瓣酱 20-30 克 （重口选 30，想吃清淡点 20 克。PS 这菜不可能太清淡，哈哈）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (336,7,'盐巴 15 克');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (336,8,'胡椒粉 10 克');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (336,9,'啤酒 400-500ml');
