INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (342,0,'将茄子切成条。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (342,1,'将肉切成肉沫，葱姜蒜切碎、小米椒切丁。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (342,2,'调鱼香汁：碗中放入盐、味精、糖、生抽、老抽、醋、水淀粉搅拌均匀。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (342,3,'锅中倒入 300ml 油，开小火（小火容易掌控），等油温七成热（小火大约 40 秒，有烟冒出）放入茄子炸两分钟，当茄子边缘微黄就捞出。多出的油可以盛出以后炒菜用。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (342,4,'锅中留 15-30ml 油，倒入肉沫炒至颜色变白就盛出来。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (342,5,'锅中倒入 15-30ml 油，放入豆瓣酱、葱白、姜、蒜炒香，然后倒入肉沫翻炒均匀。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (342,6,'加入 80-150ml 清水（水面预计茄子八成高度为准），倒入茄子、倒入料汁，爆炒入味收汁。最后放入葱翻炒均匀，就可以起锅了。');
