INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,0,'姜切片，1 颗小葱，15 颗花椒备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,1,'鸡肉洗干净，放入锅中，清水没过鸡肉，放入姜片、小葱和花椒，开大火烧开。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,2,'大火烧开后，转中小火 20 分钟关火');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,3,'取出鸡肉，放入冰水中，直至冰凉');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,4,'取出鸡肉，切块摆盘子中，备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,5,'小火把锅烧热，导入花生，烘烤至表皮爆裂。（注意随时翻动，不要糊了）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,6,'一颗葱切成段，蒜拍成末，花椒 15 颗，花生去皮切碎。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,7,'锅内导入油烧热后，放入葱段，花椒和一半蒜末，炒香');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,8,'炒至油温 8 成热，关火，滤出热油');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,9,'将热油倒入放辣椒粉的碗中，搅拌，并滤出红油');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,10,'红油中放入剩余蒜末、生抽、醋、盐、味精、糖、香油、花椒粉。拌匀放凉');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (348,11,'在鸡肉上撒上花生碎，把红油淋到切好的鸡肉上，撒上香菜。成盘');
