INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (349,0,'白鱔 250g （约一条小白鱔，已去内脏并切成段）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (349,1,'豆豉 1 汤匙');
