INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (349,7,'糖 0.5 茶匙');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (349,8,'麻油 0.5 茶匙');
