INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,0,'用剪刀 / 刀 把鸡爪上的指甲的部分全部剪掉 包括指甲下面的肉和骨头，让它一点指甲都不剩');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,1,'用水把他们洗干净，放一边');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,2,'把 鸡爪 放入大锅中，准备去腥味');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,3,'大葱 ， 料酒 ， 姜 全放进去');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,4,'加水没过 鸡爪');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,5,'大火煮开 中途可以把浮末捞起来');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,6,'水开 100度，沸腾 后等 10 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,7,'关火，捞出来，把水沥干，洗干净，放入盆里');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,8,'放入冰箱， 冷冻层 20 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,9,'把全部放入不是冷冻层的冰箱，然后分批 10个一批 拿出来去骨');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,10,'从手指（鸡爪的）最前端开始，每只手指都要用刀划开 划到它的手背部分');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,11,'再从手背部用刀分划开至整个手臂');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,12,'把每只手指关节处都掰一掰 按手指出声音时那种');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,13,'按着它的手指最前端，往里推，每只手指都一样，先推到中间手掌手背部分');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,14,'每只手指皮脱离后，从手掌开始往手臂部分推直到整个脱下来了');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,15,'放入碗中，备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,16,'小米辣 切均匀小颗');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,17,'大蒜 ， 洋葱 ， 香菜 切碎');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,18,'柠檬 对半切开，把柠檬汁挤入鸡爪的容器里');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,19,'把 全部 调料倒入装鸡爪的容器， 小米辣 ， 大蒜 ， 洋葱 和 香菜 也放进去');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,20,'抓拌均匀');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,21,'放入冰箱一个晚上（6 个小时）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (351,22,'调配好后全部放入准备好的鸡爪');
INSERT OR REPLACE INTO recipe_images (recipe_id,pos,url,local_file) VALUES (351,0,'/download/recipe-images/8b5175c6f36a40dda16d9e6454bfacb9.jpg','8b5175c6f36a40dda16d9e6454bfacb9.jpg');
