INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (351,4,'大蒜 10 瓣');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (351,5,'小米辣 4 个少辣，6 个中辣，12 个大辣（推荐大辣）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (351,6,'洋葱 （半个）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (351,7,'生抽 75g = 15g * 5');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (351,8,'蚝油 30g = 15g * 2');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (351,9,'黑醋（推荐陈醋） 50g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (351,10,'白糖 10g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (351,11,'盐 3g');
