INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (356,2,'酱油，盐，味精，料酒，姜蒜，油，豆瓣酱');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (356,0,'将五花肉条沿长边切片，每片厚 1mm-1.5mm，备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (356,1,'将切好的五花肉放置碗中，依次加入 8g 酱油，1g 盐，1g 味精，10g 料酒，两片姜，两朵拍扁的大蒜腌制 10 分钟');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (356,2,'将生菜叶直接用手扒下来，洗干净，备用');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (356,3,'热锅，倒入 5ml 食用油。油轻微冒烟后下入五花肉。单面煎制焦黄色后翻面，另一边同理。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (356,4,'五花肉出锅后，装盘。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (356,5,'将豆瓣酱抹到菜叶上，卷着五花肉即可食用');
