INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (368,1,'生抽 15ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (368,2,'酸奶或牛奶 5ml（可选）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (368,3,'鸡蛋 1 个（可选，用于裹浆）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (368,4,'蒜粉 13g');
