INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (370,12,'花椒 10 粒（约 1g，可选，提麻香）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,0,'鸡腿去骨：用剪刀从鸡腿大的那头伸进去，贴着骨头把肉剪开，再沿骨剪两下把骨肉分离，最后把骨头整根抽出。比用刀去骨更安全。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,1,'去骨后的鸡腿肉切成 2-3cm 的丁。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,2,'大葱切厚片（约 0.5cm 厚），小葱切 1cm 长的小段。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,3,'鸡腿丁加入 10ml 料酒、5ml 生抽、2g 盐、1g 白胡椒粉抓匀，腌制 10 分钟。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,4,'取一个小碗调好料汁：10ml 生抽 + 5ml 老抽 + 10ml 蚝油 + 5g 糖，搅匀备用。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,5,'热锅，锅内放入 15-20ml 食用油。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,6,'放入姜片和花椒，保持小火炸到姜片微微焦黄、花椒颜色变深。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,7,'用漏勺把姜片和花椒捞出丢弃，留底油。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,8,'保持中大火，将腌好的鸡腿丁平铺下锅，不要急着翻动。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,9,'等待 2-3 分钟让鸡腿丁底部煎出焦壳，再翻炒到所有面都变色、鸡肉完全断生。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,10,'下入大葱片，保持中大火翻炒 1 分钟炒出葱香。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,11,'倒入调好的料汁，翻炒均匀后盖上锅盖。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,12,'等待 2 分钟让料汁和葱香完全融合到鸡肉里。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (370,13,'开盖，下入小葱段和 2g 熟白芝麻（可选），翻炒 5-10 秒即可关火出锅。');
INSERT OR REPLACE INTO recipe_images (recipe_id,pos,url,local_file) VALUES (370,0,'/img/no-image.svg','no-image.svg');
