INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (370,1,'大葱 1 根（约 100g）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (370,2,'小葱 3-4 根（约 30g）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (370,3,'生抽 15ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (370,4,'老抽 5ml（上色用，没有可以全用生抽）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (370,5,'蚝油 10ml（可选，没有就多放 5ml 生抽）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (370,6,'白砂糖 5g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (370,7,'料酒 10ml');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (370,8,'盐 2-3g');
