INSERT OR REPLACE INTO recipes (id,title,category_slug,difficulty,calories,likes,favorites,last_updated,github_path,cover_image,summary,ingredients_html,calculation,calculation_html,steps_html,notes_html,markdown_html) VALUES (372,'奥尔良风味烤鸡腿','meat_dish',5,955,NULL,NULL,'08/25/2026 10:26:50','dishes/meat_dish/&#x5965;&#x5C14;&#x826F;&#x98CE;&#x5473;&#x70E4;&#x9E21;&#x817F;/&#x5965;&#x5C14;&#x826F;&#x98CE;&#x5473;&#x70E4;&#x9E21;&#x817F;.md','/img/no-image.svg','奥尔良风味烤鸡腿是一道简单易做的菜，富含蛋白质和铁。总共花费约 3 小时，其中手动操作时间约 20 分钟。','<ul>
<li>烤箱</li>
<li>烤盘</li>
<li>铝箔纸</li>
<li>手枪腿鸡腿</li>
<li>新奥尔良烤翅调料（推荐品牌 McCormick 味好美）</li>
<li>豉油调味汁（推荐品牌 日和，"薄盐肠粉豉油调味汁"）</li>
</ul>','一份正好够 1 个人吃。 每份： 手枪腿鸡腿 2 只（每个手枪腿大约重 200g，共约 400g） 新奥尔良烤翅调料 15 - 20 g 水 ≥30 mL','<p>一份正好够 1 个人吃。</p>
<p>每份：</p>
<ul>
<li>手枪腿鸡腿 2 只（每个手枪腿大约重 200g，共约 400g）</li>
<li>新奥尔良烤翅调料 15 - 20 g</li>
<li>水 ≥30 mL</li>
</ul>','<ol>
<li>解冻手枪腿鸡腿并洗净。</li>
<li>手枪腿鸡腿改花刀：在每只手枪腿鸡腿的"枪管"处，平行于"枪管"用小刀切 4-6 刀，下刀尽可能深。</li>
<li>拿一个锅，<strong>加入 15 - 20 g 新奥尔良烤翅调料粉、5 g 盐，≥30 mL 水</strong>。</li>
<li>将改完花刀的手枪腿鸡腿放入锅内，搅匀。</li>
<li>将整个锅放入冰箱冷藏层<strong>冷藏 2 - 4 小时</strong>，时间越长越入味。</li>
<li>在烤盘上放一张铝箔纸，将鸡腿取出，皮面向下放上去（不要弄破铝箔纸）。<strong>丢弃锅内剩余的液体。</strong></li>
<li>放入烤箱中上层，按照如下参数烘烤：
<em><strong>上层 230 ℃, 下层 230 ℃, 上下层烘烤, 20 分钟定时</strong></em></li>
<li>取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）</li>
<li>对所有手枪腿鸡腿翻面。</li>
<li>放入烤箱上层，按照如下参数烘烤：
<em><strong>上层 150 ℃, 下层 230 ℃, 上下层烘烤, 20 分钟定时</strong></em></li>
<li>取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）</li>
<li>放入烤箱上层，按照如下参数烘烤：
<em><strong>上层 60 ℃, 下层 60 ℃, 上下层烘烤, 15-20 分钟定时</strong></em></li>
<li>取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）</li>
<li>取一个小碗，<strong>按照 10:1 - 2:1 体积比，加入大碗中的油脂和豉油调味汁</strong>。调味汁越多越咸，具体加入量取决于个人口味。</li>
<li>抓住手枪腿鸡腿根部，蘸取小碗中的液体，可使用餐巾纸或手套隔油。现在可以直接从烤盘铝箔纸上享用奥尔良风味烤鸡腿了。
若小碗中的液体中途用尽，重复上一步。</li>
</ol>','<ul>
<li>冷藏中途可以拿出搅匀。冷藏时间切勿过长。</li>
<li>该指南基于的烤箱参数为_<strong>容积 25 L，功率 1400 W</strong>_。
若烤箱功率低于/高于此值，可以适当延长/缩短烤箱定时，但请确保鸡腿是熟的。</li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>','<h1>奥尔良风味烤鸡腿</h1>
<p>奥尔良风味烤鸡腿是一道简单易做的菜，富含蛋白质和铁。总共花费约 3 小时，其中手动操作时间约 20 分钟。</p>
<p><strong>估算卡路里：955 kcal</strong></p>
<h2>原料和工具</h2>
<ul>
<li>烤箱</li>
<li>烤盘</li>
<li>铝箔纸</li>
<li>手枪腿鸡腿</li>
<li>新奥尔良烤翅调料（推荐品牌 McCormick 味好美）</li>
<li>豉油调味汁（推荐品牌 日和，"薄盐肠粉豉油调味汁"）</li>
</ul>
<h2>计算</h2>
<p>一份正好够 1 个人吃。</p>
<p>每份：</p>
<ul>
<li>手枪腿鸡腿 2 只（每个手枪腿大约重 200g，共约 400g）</li>
<li>新奥尔良烤翅调料 15 - 20 g</li>
<li>水 ≥30 mL</li>
</ul>
<h2>步骤</h2>
<ol>
<li>解冻手枪腿鸡腿并洗净。</li>
<li>手枪腿鸡腿改花刀：在每只手枪腿鸡腿的"枪管"处，平行于"枪管"用小刀切 4-6 刀，下刀尽可能深。</li>
<li>拿一个锅，<strong>加入 15 - 20 g 新奥尔良烤翅调料粉、5 g 盐，≥30 mL 水</strong>。</li>
<li>将改完花刀的手枪腿鸡腿放入锅内，搅匀。</li>
<li>将整个锅放入冰箱冷藏层<strong>冷藏 2 - 4 小时</strong>，时间越长越入味。</li>
<li>在烤盘上放一张铝箔纸，将鸡腿取出，皮面向下放上去（不要弄破铝箔纸）。<strong>丢弃锅内剩余的液体。</strong></li>
<li>放入烤箱中上层，按照如下参数烘烤：
<em><strong>上层 230 ℃, 下层 230 ℃, 上下层烘烤, 20 分钟定时</strong></em></li>
<li>取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）</li>
<li>对所有手枪腿鸡腿翻面。</li>
<li>放入烤箱上层，按照如下参数烘烤：
<em><strong>上层 150 ℃, 下层 230 ℃, 上下层烘烤, 20 分钟定时</strong></em></li>
<li>取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）</li>
<li>放入烤箱上层，按照如下参数烘烤：
<em><strong>上层 60 ℃, 下层 60 ℃, 上下层烘烤, 15-20 分钟定时</strong></em></li>
<li>取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）</li>
<li>取一个小碗，<strong>按照 10:1 - 2:1 体积比，加入大碗中的油脂和豉油调味汁</strong>。调味汁越多越咸，具体加入量取决于个人口味。</li>
<li>抓住手枪腿鸡腿根部，蘸取小碗中的液体，可使用餐巾纸或手套隔油。现在可以直接从烤盘铝箔纸上享用奥尔良风味烤鸡腿了。
若小碗中的液体中途用尽，重复上一步。</li>
</ol>
<h2>补充说明</h2>
<ul>
<li>冷藏中途可以拿出搅匀。冷藏时间切勿过长。</li>
<li>该指南基于的烤箱参数为_<strong>容积 25 L，功率 1400 W</strong>_。
若烤箱功率低于/高于此值，可以适当延长/缩短烤箱定时，但请确保鸡腿是熟的。</li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (372,0,'烤箱');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (372,1,'烤盘');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (372,2,'铝箔纸');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (372,3,'手枪腿鸡腿');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (372,4,'新奥尔良烤翅调料（推荐品牌 McCormick 味好美）');
INSERT OR REPLACE INTO recipe_ingredients (recipe_id,pos,name) VALUES (372,5,'豉油调味汁（推荐品牌 日和，"薄盐肠粉豉油调味汁"）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,0,'解冻手枪腿鸡腿并洗净。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,1,'手枪腿鸡腿改花刀：在每只手枪腿鸡腿的"枪管"处，平行于"枪管"用小刀切 4-6 刀，下刀尽可能深。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,2,'拿一个锅， 加入 15 - 20 g 新奥尔良烤翅调料粉、5 g 盐，≥30 mL 水 。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,3,'将改完花刀的手枪腿鸡腿放入锅内，搅匀。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,4,'将整个锅放入冰箱冷藏层 冷藏 2 - 4 小时 ，时间越长越入味。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,5,'在烤盘上放一张铝箔纸，将鸡腿取出，皮面向下放上去（不要弄破铝箔纸）。 丢弃锅内剩余的液体。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,6,'放入烤箱中上层，按照如下参数烘烤： 上层 230 ℃, 下层 230 ℃, 上下层烘烤, 20 分钟定时');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,7,'取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,8,'对所有手枪腿鸡腿翻面。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,9,'放入烤箱上层，按照如下参数烘烤： 上层 150 ℃, 下层 230 ℃, 上下层烘烤, 20 分钟定时');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,10,'取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,11,'放入烤箱上层，按照如下参数烘烤： 上层 60 ℃, 下层 60 ℃, 上下层烘烤, 15-20 分钟定时');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,12,'取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,13,'取一个小碗， 按照 10:1 - 2:1 体积比，加入大碗中的油脂和豉油调味汁 。调味汁越多越咸，具体加入量取决于个人口味。');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (372,14,'抓住手枪腿鸡腿根部，蘸取小碗中的液体，可使用餐巾纸或手套隔油。现在可以直接从烤盘铝箔纸上享用奥尔良风味烤鸡腿了。 若小碗中的液体中途用尽，重复上一步。');
INSERT OR REPLACE INTO recipe_images (recipe_id,pos,url,local_file) VALUES (372,0,'/img/no-image.svg','no-image.svg');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (372,0,'手枪腿鸡腿 2 只（每个手枪腿大约重 200g，共约 400g）');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (372,1,'新奥尔良烤翅调料 15 - 20 g');
INSERT OR REPLACE INTO recipe_calculation_items (recipe_id,pos,item) VALUES (372,2,'水 ≥30 mL');
INSERT OR REPLACE INTO recipes (id,title,category_slug,difficulty,calories,likes,favorites,last_updated,github_path,cover_image,summary,ingredients_html,calculation,calculation_html,steps_html,notes_html,markdown_html) VALUES (373,'滕州菜煎饼','staple',2,800,NULL,NULL,'09/03/2026 14:26:55','dishes/staple/&#x6ED5;&#x5DDE;&#x83DC;&#x714E;&#x997C;.md','/img/no-image.svg','滕州菜煎饼是山东省滕州市的传统小吃，创始于清代，由王牛臯创制。以白面煎饼包裹白菜、粉条、豆腐等时令蔬菜，搭配鸡蛋、火腿肠，调以油与香料煎烙而成。成品外酥内软、鲜香爽口，适合作为主食或早餐，从备料到出锅大约 15 分钟即可完成。','<ul>
<li>白面煎饼（市售山东煎饼，或自制）</li>
<li>白菜</li>
<li>粉条（干）</li>
<li>豆腐</li>
<li>胡萝卜</li>
<li>韭菜（可选）</li>
<li>鸡蛋</li>
<li>火腿肠（可选）</li>
<li>食用油</li>
<li>食盐</li>
<li>味精（可选）</li>
<li>孜然粉</li>
<li>辣椒粉（可选）</li>
<li>黑胡椒粉</li>
<li>鏊子 或 平底不粘锅（直径不小于 28 cm）</li>
</ul>','每次制作前需要确定计划做几份。一份正好够 1 个人食用。 总量： 白面煎饼数量 = 份数 * 2 张 白菜 = 份数 * 100 g 粉条（干重） = 份数 * 50 g 豆腐 = 份数 * 80 g 胡萝卜 = 份数 * 50 g 韭菜 = 份数 * 30 g（可选） 鸡蛋 = 份数 * 1 个 火腿肠 = 份数 * 40 g（可选） 食用油 = 份数 * 20 ml 食盐 = 份数 * 2 g 味精 = 份数 * 1 g（可选） 孜然粉 = 份数 * 2 g 辣椒粉 = 份数 * 2 g（可选） 黑胡椒粉 = 份数 * 1 g','<p>每次制作前需要确定计划做几份。一份正好够 1 个人食用。</p>
<p>总量：</p>
<ul>
<li>白面煎饼数量 = 份数 * 2 张</li>
<li>白菜 = 份数 * 100 g</li>
<li>粉条（干重） = 份数 * 50 g</li>
<li>豆腐 = 份数 * 80 g</li>
<li>胡萝卜 = 份数 * 50 g</li>
<li>韭菜 = 份数 * 30 g（可选）</li>
<li>鸡蛋 = 份数 * 1 个</li>
<li>火腿肠 = 份数 * 40 g（可选）</li>
<li>食用油 = 份数 * 20 ml</li>
<li>食盐 = 份数 * 2 g</li>
<li>味精 = 份数 * 1 g（可选）</li>
<li>孜然粉 = 份数 * 2 g</li>
<li>辣椒粉 = 份数 * 2 g（可选）</li>
<li>黑胡椒粉 = 份数 * 1 g</li>
</ul>','<ol>
<li>粉条放入温水中浸泡 10 分钟至变软，捞出沥干，切成不超过 5 cm 的段，备用</li>
<li>白菜洗净，切成不超过 1 cm 宽的细丝；胡萝卜去皮，切成不超过 1 cm 的细丝；豆腐切成不超过 1 cm 见方的小丁；韭菜洗净，切成不超过 1 cm 的段。全部放入拌碗</li>
<li>在拌碗中依次加入食用油 15 ml、食盐 2 g、味精 1 g、孜然粉 2 g、黑胡椒粉 1 g、辣椒粉 2 g，用筷子搅拌均匀，使蔬菜表面均匀裹上调料，备用</li>
<li>平底锅（或鏊子）中火预热，倒入食用油 5 ml 并转动锅体使油铺满锅面。打入鸡蛋，用锅铲将蛋清与蛋黄打散，摊成比煎饼略小的圆形薄蛋皮</li>
<li>取 1 张煎饼平铺在蛋皮上，使蛋皮贴服于煎饼，将煎饼连蛋皮翻面（蛋皮朝上），转小火备用</li>
<li>将拌好的蔬菜均匀铺在煎饼（蛋皮朝上）表面，边缘留约 1 cm 不铺菜，防止折叠时漏出</li>
<li>取第 2 张煎饼覆盖在蔬菜上方，用锅铲轻轻按压使两层煎饼贴合</li>
<li>开中小火加热 2 分钟至底部微黄，用锅铲将整张菜煎饼翻面，继续加热 2 分钟至另一面微黄、油润</li>
<li>转最小火继续加热 1 分钟，至两面均呈金黄色、蔬菜熟透（可用筷子插入中心，确认无生蔬菜的阻力）</li>
<li>关火，将菜煎饼两边向中间折叠成约 10 cm 宽的长方形，用锅铲或刀从中间一分为二，盛盘</li>
</ol>','<ul>
<li>蔬菜可按喜好替换：菠菜、南瓜、水萝卜、荠菜等均可，单份蔬菜总量保持在 300-350 g</li>
<li>菜煎饼适合趁热食用；常温放置超过 30 分钟会变软，失去酥脆口感</li>
<li>若无鏊子，用直径不小于 28 cm 的平底不粘锅即可，注意火候不宜过大以免煎饼焦糊</li>
<li>白面煎饼可市购；也可用面粉 100 g 加饮用水 150 ml 调成稀面糊，在平底锅上摊制</li>
<li>参考资料：<a href="https://baike.baidu.com/item/%E6%BB%95%E5%B7%9E%E8%8F%9C%E7%85%8E%E9%A5%BC/2512643">滕州菜煎饼 - 百度百科</a></li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>','<h1>滕州菜煎饼</h1>
<p>滕州菜煎饼是山东省滕州市的传统小吃，创始于清代，由王牛臯创制。以白面煎饼包裹白菜、粉条、豆腐等时令蔬菜，搭配鸡蛋、火腿肠，调以油与香料煎烙而成。成品外酥内软、鲜香爽口，适合作为主食或早餐，从备料到出锅大约 15 分钟即可完成。</p>
<p><strong>估算卡路里：800 kcal</strong></p>
<h2>原料和工具</h2>
<ul>
<li>白面煎饼（市售山东煎饼，或自制）</li>
<li>白菜</li>
<li>粉条（干）</li>
<li>豆腐</li>
<li>胡萝卜</li>
<li>韭菜（可选）</li>
<li>鸡蛋</li>
<li>火腿肠（可选）</li>
<li>食用油</li>
<li>食盐</li>
<li>味精（可选）</li>
<li>孜然粉</li>
<li>辣椒粉（可选）</li>
<li>黑胡椒粉</li>
<li>鏊子 或 平底不粘锅（直径不小于 28 cm）</li>
</ul>
<h2>计算</h2>
<p>每次制作前需要确定计划做几份。一份正好够 1 个人食用。</p>
<p>总量：</p>
<ul>
<li>白面煎饼数量 = 份数 * 2 张</li>
<li>白菜 = 份数 * 100 g</li>
<li>粉条（干重） = 份数 * 50 g</li>
<li>豆腐 = 份数 * 80 g</li>
<li>胡萝卜 = 份数 * 50 g</li>
<li>韭菜 = 份数 * 30 g（可选）</li>
<li>鸡蛋 = 份数 * 1 个</li>
<li>火腿肠 = 份数 * 40 g（可选）</li>
<li>食用油 = 份数 * 20 ml</li>
<li>食盐 = 份数 * 2 g</li>
<li>味精 = 份数 * 1 g（可选）</li>
<li>孜然粉 = 份数 * 2 g</li>
<li>辣椒粉 = 份数 * 2 g（可选）</li>
<li>黑胡椒粉 = 份数 * 1 g</li>
</ul>
<h2>步骤</h2>
<ol>
<li>粉条放入温水中浸泡 10 分钟至变软，捞出沥干，切成不超过 5 cm 的段，备用</li>
<li>白菜洗净，切成不超过 1 cm 宽的细丝；胡萝卜去皮，切成不超过 1 cm 的细丝；豆腐切成不超过 1 cm 见方的小丁；韭菜洗净，切成不超过 1 cm 的段。全部放入拌碗</li>
<li>在拌碗中依次加入食用油 15 ml、食盐 2 g、味精 1 g、孜然粉 2 g、黑胡椒粉 1 g、辣椒粉 2 g，用筷子搅拌均匀，使蔬菜表面均匀裹上调料，备用</li>
<li>平底锅（或鏊子）中火预热，倒入食用油 5 ml 并转动锅体使油铺满锅面。打入鸡蛋，用锅铲将蛋清与蛋黄打散，摊成比煎饼略小的圆形薄蛋皮</li>
<li>取 1 张煎饼平铺在蛋皮上，使蛋皮贴服于煎饼，将煎饼连蛋皮翻面（蛋皮朝上），转小火备用</li>
<li>将拌好的蔬菜均匀铺在煎饼（蛋皮朝上）表面，边缘留约 1 cm 不铺菜，防止折叠时漏出</li>
<li>取第 2 张煎饼覆盖在蔬菜上方，用锅铲轻轻按压使两层煎饼贴合</li>
<li>开中小火加热 2 分钟至底部微黄，用锅铲将整张菜煎饼翻面，继续加热 2 分钟至另一面微黄、油润</li>
<li>转最小火继续加热 1 分钟，至两面均呈金黄色、蔬菜熟透（可用筷子插入中心，确认无生蔬菜的阻力）</li>
<li>关火，将菜煎饼两边向中间折叠成约 10 cm 宽的长方形，用锅铲或刀从中间一分为二，盛盘</li>
</ol>
<h2>补充说明</h2>
<ul>
<li>蔬菜可按喜好替换：菠菜、南瓜、水萝卜、荠菜等均可，单份蔬菜总量保持在 300-350 g</li>
<li>菜煎饼适合趁热食用；常温放置超过 30 分钟会变软，失去酥脆口感</li>
<li>若无鏊子，用直径不小于 28 cm 的平底不粘锅即可，注意火候不宜过大以免煎饼焦糊</li>
<li>白面煎饼可市购；也可用面粉 100 g 加饮用水 150 ml 调成稀面糊，在平底锅上摊制</li>
<li>参考资料：<a href="https://baike.baidu.com/item/%E6%BB%95%E5%B7%9E%E8%8F%9C%E7%85%8E%E9%A5%BC/2512643">滕州菜煎饼 - 百度百科</a></li>
</ul>
<p>如果您遵循本指南的制作流程而发现有问题或可以改进的流程，请提出 Issue 或 Pull request 。</p>');
