INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (373,7,'开中小火加热 2 分钟至底部微黄，用锅铲将整张菜煎饼翻面，继续加热 2 分钟至另一面微黄、油润');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (373,8,'转最小火继续加热 1 分钟，至两面均呈金黄色、蔬菜熟透（可用筷子插入中心，确认无生蔬菜的阻力）');
INSERT OR REPLACE INTO recipe_steps (recipe_id,pos,text) VALUES (373,9,'关火，将菜煎饼两边向中间折叠成约 10 cm 宽的长方形，用锅铲或刀从中间一分为二，盛盘');
